/**
 * Emits TypeScript contract files from the generator IR.
 *
 * The output is plain, readable code against the runtime DSL — the same
 * `defineApi` / `contract` / `P` API you would write by hand — so generated
 * connectors remain fully typed, diffable and editable.
 */

import type { ApiGroupIR, ApiIR, OperationIR, ParamIR, SchemaIR } from './openapi.js';

export interface EmitOptions {
  /** Module specifier the generated files import from. Default `contractful-ts`. */
  importFrom?: string;
  /** Rendered in the file header. */
  specOrigin?: string;
  /** Include the group index re-exporting every emitted `defineApi` const. */
  emitIndex?: boolean;
  /** How many operations per file before splitting (0 = never split). */
  maxPerFile?: number;
}

export interface EmittedFile {
  /** Relative path (POSIX) within the output directory. */
  path: string;
  content: string;
}

const DESCRIBE_MAX_LENGTH = 160;

export function emitContracts(ir: ApiIR, options: EmitOptions = {}): EmittedFile[] {
  const importFrom = options.importFrom ?? 'contractful-ts';
  const files: EmittedFile[] = [];
  const indexExports: { constName: string; file: string }[] = [];

  for (const group of ir.groups) {
    if (group.operations.length === 0) continue;

    const maxPerFile = options.maxPerFile ?? 0;
    const chunks =
      maxPerFile > 0 ? chunk(group.operations, maxPerFile) : [group.operations];

    chunks.forEach((chunk, i) => {
      const multi = chunks.length > 1;
      const suffix = multi ? `-part-${i + 1}` : '';
      const constName = group.constName + (multi ? `Part${i + 1}` : '');
      const fileName = group.fileName.replace(/\.ts$/, `${suffix}.ts`);

      files.push({
        path: fileName,
        content: emitGroupFile(ir, group.name, constName, chunk, importFrom, options),
      });
      indexExports.push({ constName, file: fileName.replace(/\.ts$/, '') });
    });
  }

  if ((options.emitIndex ?? true) && indexExports.length > 0) {
    files.push({
      path: 'index.ts',
      content: [
        `// Auto-generated by contractful-gen from ${originLabel(options.specOrigin)} — DO NOT EDIT.`,
        ...indexExports.map((entry) => `export * from './${entry.file}.js';`),
        '',
      ].join('\n'),
    });
  }

  return files;
}

function emitGroupFile(
  ir: ApiIR,
  groupName: string,
  constName: string,
  operations: OperationIR[],
  importFrom: string,
  options: EmitOptions,
): string {
  const lines: string[] = [];
  lines.push(`// Auto-generated by contractful-gen from ${originLabel(options.specOrigin)} — DO NOT EDIT.`);
  lines.push(`// API: ${ir.title}${ir.version ? ` (${ir.version})` : ''} · group: ${groupName}`);
  lines.push(`// Review constraints and response shapes before shipping; unknown response fields are open.`);
  lines.push('');
  lines.push(`import { defineApi, contract, P } from ${JSON.stringify(importFrom)};`);
  lines.push('');
  lines.push(`export const ${constName} = defineApi({`);
  lines.push(`  name: ${JSON.stringify(`${ir.title} · ${groupName}`)},`);
  lines.push(`  base: ${JSON.stringify(ir.base)},`);
  if (operations.some((op) => op.responds.length === 0)) {
    lines.push(`  // NOTE: some operations declare no responses; all 2xx are accepted.`);
  }
  lines.push('  contracts: {');
  for (const op of operations) {
    emitOperation(lines, op);
  }
  lines.push('  },');
  lines.push('});');
  lines.push('');
  return lines.join('\n');
}

function emitOperation(lines: string[], op: OperationIR): void {
  const doc = [op.summary, op.description].filter(Boolean).join(' — ');
  if (doc) lines.push(`    /** ${escapeComment(clamp(doc))} */`);
  lines.push(`    ${op.name}: contract(${JSON.stringify(`${op.method} ${op.path}`)}, {`);

  if (op.params.length > 0) {
    lines.push('      params: {');
    for (const param of op.params) {
      emitParam(lines, param);
    }
    lines.push('      },');
  }

  if (op.responds.length > 0) {
    lines.push(
      `      responds: [${op.responds
        .map((r) => `{ status: ${r.status}${r.type ? `, type: ${JSON.stringify(r.type)}` : ''} }`)
        .join(', ')}],`,
    );
  }

  lines.push('    }),');
}

function emitParam(lines: string[], param: ParamIR): void {
  const args: string[] = [];
  if (param.required) args.push('required: true');
  if (param.tsName !== param.wireName) args.push(`as: ${JSON.stringify(param.wireName)}`);
  // Path placement is derived from the route template; everything else is
  // stated explicitly so generated code stays unambiguous.
  if (param.location === 'query' || param.location === 'header' || param.location === 'body') {
    args.push(`in: ${JSON.stringify(param.location)}`);
  }
  args.push(...schemaConstraintArgs(param.schema));
  const describe = param.schema.description ?? param.description;
  if (describe) {
    args.push(`describe: ${JSON.stringify(clamp(describe))}`);
  }

  lines.push(`        ${param.tsName}: P.${emitKind(param.schema)}(${formatArgs(args)}),`);
}

function emitKind(schema: SchemaIR): string {
  switch (schema.type) {
    case 'integer':
      return 'integer';
    case 'number':
      return 'float';
    case 'boolean':
      return 'boolean';
    case 'array':
      return 'array';
    case 'object':
      return 'hash';
    case 'string':
    default:
      return 'string';
  }
}

function schemaConstraintArgs(schema: SchemaIR): string[] {
  const args: string[] = [];
  const kind = emitKind(schema);

  if (schema.default !== undefined) {
    args.push(`default: ${JSON.stringify(schema.default)}`);
  }
  if (schema.enumValues && schema.enumValues.length > 0 && (kind === 'string' || kind === 'integer' || kind === 'float')) {
    args.push(`inclusion: [${schema.enumValues.map((v) => JSON.stringify(v)).join(', ')}]`);
  }
  if (kind === 'integer' || kind === 'float') {
    if (schema.minimum !== undefined) args.push(`min: ${schema.minimum}`);
    if (schema.maximum !== undefined) args.push(`max: ${schema.maximum}`);
  }
  if (kind === 'string') {
    if (schema.minLength !== undefined || schema.maxLength !== undefined) {
      const parts: string[] = [];
      if (schema.minLength !== undefined) parts.push(`min: ${schema.minLength}`);
      if (schema.maxLength !== undefined) parts.push(`max: ${schema.maxLength}`);
      args.push(`length: { ${parts.join(', ')} }`);
    }
    if (schema.pattern) args.push(`pattern: new RegExp(${JSON.stringify(schema.pattern)})`);
  }
  if (kind === 'array' && schema.items) {
    const innerArgs = schemaConstraintArgs(schema.items);
    const innerKind = emitKind(schema.items);
    args.push(`of: P.${innerKind}(${formatArgs(innerArgs)})`);
  }

  return args;
}

function formatArgs(args: string[]): string {
  if (args.length === 0) return '';
  return `{ ${args.join(', ')} }`;
}

function escapeComment(text: string): string {
  return text.replace(/\*\//g, '*​/').replace(/\s+/g, ' ').trim();
}

function clamp(text: string): string {
  const single = text.replace(/\s+/g, ' ').trim();
  if (single.length <= DESCRIBE_MAX_LENGTH) return single;
  return `${single.slice(0, DESCRIBE_MAX_LENGTH - 1)}…`;
}

function chunk<T>(items: T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

function originLabel(origin?: string): string {
  return origin ?? 'OpenAPI spec';
}
